// Steam + Millennium: meldet Installation und laufende Downloads an App/Web-UI.
// Nur Lesen: die Daten kommen vom Agenten (pc.steam()), nicht aus Dateien.
var stand = {};      // app_id -> { name, prozent, stufe }
var statusZeile = "";
var gemeldet = {};   // einmalige Hinweise (kein Dauer-Spam im Journal)
var steamLief = null;

function zahl(wert) {
  var n = Number(wert);
  return isFinite(n) ? n : 0;
}

// Fortschritt immer mit genau einer Nachkommastelle.
function prozentText(wert) {
  return zahl(wert).toFixed(1);
}

// Name eines Downloads, mit Ersatzname falls das Feld fehlt.
function nameVon(eintrag, nummer) {
  var name = eintrag && eintrag.name ? String(eintrag.name) : "";
  if (name === "") {
    name = "App " + String(eintrag && eintrag.app_id ? eintrag.app_id : nummer);
  }
  return name;
}

// "4.2 MB/s" - der Agent liefert Bytes pro Sekunde (speed_bps).
// Netzwerk-Tempo wird dezimal gerechnet (wie im Steam-Client), nicht binaer.
function tempoText(bps) {
  var wert = zahl(bps);
  if (wert <= 0) {
    return "";
  }
  if (wert >= 1000000000) {
    return (wert / 1000000000).toFixed(1) + " GB/s";
  }
  if (wert >= 1000000) {
    return (wert / 1000000).toFixed(1) + " MB/s";
  }
  if (wert >= 1000) {
    return Math.round(wert / 1000) + " KB/s";
  }
  return Math.round(wert) + " B/s";
}

// "noch 12 Min." - Restzeit aus eta_seconds.
function restText(sekunden) {
  var s = zahl(sekunden);
  if (s <= 0) {
    return "";
  }
  if (s < 60) {
    return "noch " + Math.round(s) + " s";
  }
  if (s < 3600) {
    return "noch " + Math.round(s / 60) + " Min.";
  }
  return "noch " + Math.floor(s / 3600) + " Std. " + Math.round((s % 3600) / 60) + " Min.";
}

function einmalig(schluessel, text) {
  if (gemeldet[schluessel]) {
    return;
  }
  gemeldet[schluessel] = true;
  pc.log(text);
}

function activate() {
  stand = {};
  statusZeile = "";
  gemeldet = {};
  steamLief = null;
  var status = pc.steam();
  if (!status || !status.detected) {
    einmalig("kein-steam", "Steam nicht erkannt - kein Steam-Pfad gefunden.");
    pc.log("> Steam fehlt (Pfad pruefen oder Steam installieren)");
    pc.setStatus("");
    return;
  }
  pc.log("Steam erkannt: " + String(status.steam_path));
  pc.log("Millennium: " + (status.millennium ? "erkannt" : "nicht erkannt"));
  pc.log("Steam laeuft: " + (status.running ? "ja" : "nein"));
  if (!status.millennium) {
    pc.log("Hinweis: Millennium wird nur erkannt, nicht installiert.");
  }
}

function tick() {
  var status = pc.steam();
  if (!status || !status.detected) {
    return;
  }

  // Steam-Start/-Ende je Wechsel einmal melden.
  if (steamLief !== null && steamLief !== !!status.running) {
    pc.log("> Steam " + (status.running ? "gestartet" : "beendet"));
  }
  steamLief = !!status.running;

  var liste = status.downloads || [];
  var jetzt = {};
  var zeilen = [];
  var prozente = [];
  var i;
  for (i = 0; i < liste.length; i = i + 1) {
    var eintrag = liste[i] || {};
    var id = String(eintrag.app_id || ("?" + i));
    var name = nameVon(eintrag, i + 1);
    var prozent = zahl(eintrag.percent);
    var vorher = stand[id];
    var stufe = Math.floor(prozent / 10);

    if (!vorher) {
      pc.log("> Download gestartet: " + name + " (" + prozentText(prozent) + " %)");
    } else if (stufe > vorher.stufe) {
      // Fortschritt in 10-%-Schritten - reicht fuer das Journal.
      pc.log("> " + name + ": " + (stufe * 10) + " %");
    }
    jetzt[id] = {
      name: name,
      prozent: prozent,
      stufe: vorher ? Math.max(vorher.stufe, stufe) : stufe
    };
    prozente.push(prozent);

    var teile = [prozentText(prozent) + " %"];
    var tempo = tempoText(eintrag.speed_bps);
    if (tempo !== "") {
      teile.push(tempo);
    }
    var rest = restText(eintrag.eta_seconds);
    if (rest !== "") {
      teile.push(rest);
    }
    zeilen.push(name + " " + teile.join(" · "));
  }

  // Verschwundene Downloads: fertig oder abgebrochen (einmalig mit ">").
  var offen;
  for (offen in stand) {
    if (!jetzt[offen]) {
      var alt = stand[offen];
      if (alt.prozent >= 99) {
        pc.log("> Download fertig: " + alt.name);
      } else {
        pc.log("> Download beendet: " + alt.name + " bei " + prozentText(alt.prozent) + " %");
      }
    }
  }
  stand = jetzt;

  if (zeilen.length === 0) {
    if (statusZeile !== "") {
      pc.log("Keine Downloads mehr aktiv.");
      statusZeile = "";
    }
    pc.setStatus("");
    return;
  }

  // Statuszeile: bei mehreren Downloads den am weitesten fortgeschrittenen
  // zeigen, die Anzahl aber nicht verschweigen.
  var haupt = 0;
  for (i = 1; i < prozente.length; i = i + 1) {
    if (prozente[i] > prozente[haupt]) {
      haupt = i;
    }
  }
  var kurz = zeilen.length === 1
    ? "Steam: " + zeilen[0]
    : "Steam: " + zeilen.length + " Downloads - " + zeilen[haupt];
  // Nur bei Aenderung schreiben, damit Journal und Status ruhig bleiben.
  if (kurz !== statusZeile) {
    pc.setStatus(kurz);
    pc.log(kurz);
    statusZeile = kurz;
  }
}

function stop() {
  pc.setStatus("");
  pc.log("> Steam-Ueberwachung beendet");
}
